/**
 * Список задач + метрики по каждой задаче, посчитанные из history.json
 * (колонка «Метрики» в таблице дашборда).
 */
async function collectTasksWithMetrics(deps) {
    const [history, tasks] = await Promise.all([loadHistory(), deps.getTasks()]);
    const byTask = new Map();
    for (const r of history) {
        const key = String(r.taskName || "").toLowerCase();
        if (!key)
            continue;
        const m = byTask.get(key) ?? { total: 0, success: 0, error: 0, partial: 0, running: 0 };
        m.total += 1;
        if (r.status === "success")
            m.success += 1;
        else if (r.status === "partial")
            m.partial += 1;
        else if (r.status === "running")
            m.running += 1;
        else
            m.error += 1;
        byTask.set(key, m);
    }
    return tasks.map((t) => ({
        ...t,
        metrics: byTask.get(String(t.name).toLowerCase()) ?? {
            total: 0,
            success: 0,
            error: 0,
            partial: 0,
            running: 0,
        },
    }));
}
